// Общие шаги для назначения/снятия техника на странице работы (#04d33a [F-3]). Admin, компания «test», EN.
// Работа — одна постоянная «QA-AUTO 04d33a job» (клиент QA-quota client), переиспользуется между прогонами;
// в конце прогона она остаётся в Submitted без техника. Техники — только QA-Tech Alpha/Beta (без согласия на SMS).
import * as fs from 'fs';
import * as path from 'path';
import { expect, Locator, Page } from '@playwright/test';
import { jobRow, openJobsTab, statusSelect } from '../job-closed-date/closed-helpers';
import { pickTech } from '../multi-tech-assignment/multi-tech-helpers';

export { statusSelect };

export const JOB_TITLE = 'QA-AUTO 04d33a job';
export const ALPHA = 'QA-Tech Alpha';
export const BETA = 'QA-Tech Beta';

/** Адрес найденной/созданной работы запоминается между прогонами, чтобы не плодить работы. */
const CACHE = path.resolve(__dirname, '../../.cache/qa-auto-04d33a-job.json');

const esc = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

/** Окно «Leave site?» (beforeunload) — подтверждаем: перезагрузку делаем только после сохранения. */
export function acceptLeaveDialogs(page: Page) {
  page.on('dialog', (d) => (d.type() === 'beforeunload' ? d.accept() : d.dismiss()).catch(() => {}));
}

/**
 * Блок Assign Technician на странице работы: самый внутренний div с подписью и выпадающим списком.
 * // не проверено на сайте при записи: доступное имя combobox на JobDetail — поэтому ищем по подписи блока.
 */
export function assignSection(page: Page): Locator {
  return page.locator('div')
    .filter({ has: page.getByText('Assign Technician', { exact: true }) })
    .filter({ has: page.getByRole('combobox') })
    .last();
}

export const assignCombo = (page: Page): Locator => assignSection(page).getByRole('combobox').first();

/** Кнопка X рядом с Assign Technician (aria-label «Take <tech> off the job»). */
export const takeOffButton = (page: Page, tech: string): Locator =>
  page.getByRole('button', { name: `Take ${tech} off the job`, exact: true });
export const anyTakeOffButton = (page: Page): Locator =>
  page.getByRole('button', { name: /^Take .+ off the job$/ });

/** Поле пустое: «Select technician» (текст или placeholder). */
export async function expectNoTechnician(page: Page) {
  const section = assignSection(page);
  await expect(
    section.getByText('Select technician', { exact: true }).or(section.getByPlaceholder('Select technician')).first(),
  ).toBeVisible({ timeout: 20_000 });
  await expect(section).not.toContainText(/QA-Tech (Alpha|Beta)/);
  await expect(anyTakeOffButton(page), 'без техника кнопки X нет').toHaveCount(0);
}

export async function expectTechnician(page: Page, tech: string) {
  await expect(assignSection(page)).toContainText(tech, { timeout: 20_000 });
  await expect(takeOffButton(page, tech)).toBeVisible();
}

export async function expectStatus(page: Page, status: 'Submitted' | 'Assigned') {
  await expect(statusSelect(page)).toHaveText(status, { timeout: 20_000 });
}

/** Заголовки строк истории назначений (новая строка — сверху). */
const HISTORY_TITLE = /^(Assigned to .+|Reassigned from .+ to .+|.+ taken off the job)$/;
export const historyTitles = (page: Page): Locator => page.getByText(HISTORY_TITLE);

/** Верхняя (последняя по времени) строка истории — ждём, пока она станет нужной (это и есть признак автосохранения). */
export async function expectLatestHistory(page: Page, title: string) {
  await expect(page.getByText('Assignment history', { exact: true })).toBeVisible({ timeout: 20_000 });
  await expect(historyTitles(page).first(), `верхняя строка истории — «${title}»`).toHaveText(title, { timeout: 30_000 });
}

/**
 * Карточка верхней строки истории: ближайший предок заголовка, в котором есть строка «… · by <email>».
 * // не проверено на сайте при записи: разметка карточки (на скрине — заголовок, «дата · by email», текст, плашка + кнопка).
 */
export const latestHistoryEntry = (page: Page): Locator =>
  historyTitles(page).first().locator('xpath=ancestor::*[contains(normalize-space(.), "· by ")][1]');

export async function assignTech(page: Page, tech: string) {
  await pickTech(page, assignCombo(page), tech);
}

/** Снять техника кнопкой X, если он есть (подготовка/очистка). */
export async function ensureNoTechnician(page: Page) {
  const x = anyTakeOffButton(page);
  if (await x.count()) {
    const label = (await x.first().getAttribute('aria-label')) ?? '';
    const tech = label.replace(/^Take /, '').replace(/ off the job$/, '');
    await x.first().click();
    await expectNoTechnician(page);
    if (tech) await expectLatestHistory(page, `${tech} taken off the job`);
  }
  await expectNoTechnician(page);
}

/** Страница работы загружена и это наша работа (описание «QA-AUTO 04d33a job»), статус Submitted/Assigned. */
async function isOurJob(page: Page): Promise<boolean> {
  const desc = page.getByLabel('Job Description');
  try {
    await expect(desc).toHaveValue(new RegExp(esc(JOB_TITLE)), { timeout: 20_000 });
    await expect(statusSelect(page)).toHaveText(/^(Submitted|Assigned)$/, { timeout: 10_000 });
    return true;
  } catch {
    return false;
  }
}

function readCache(): string | undefined {
  try {
    return JSON.parse(fs.readFileSync(CACHE, 'utf8')).url;
  } catch {
    return undefined;
  }
}

function writeCache(url: string, jobId: string) {
  fs.mkdirSync(path.dirname(CACHE), { recursive: true });
  fs.writeFileSync(CACHE, JSON.stringify({ url, jobId, title: JOB_TITLE }, null, 2));
}

/**
 * Открыть работу «QA-AUTO 04d33a job»: 1) адрес из кэша; 2) поиск во вкладке Submitted; 3) создать (без техника).
 * Возвращает адрес страницы работы и номер JOB-….
 * // не проверено на сайте при записи: ищет ли «Search jobs…» по описанию работы и открывает ли клик по строке страницу работы.
 */
export async function openQaJob(page: Page): Promise<{ url: string; jobId: string }> {
  const cached = readCache();
  if (cached) {
    await page.goto(cached);
    if (await isOurJob(page)) return { url: cached, jobId: await readJobId(page) };
  }

  await openJobsTab(page, 'Submitted');
  await page.getByPlaceholder(/^Search jobs/i).fill(JOB_TITLE);
  const row = page.locator('main tbody tr').filter({ hasText: /JOB-\d+/ }).first();
  if (await row.isVisible({ timeout: 10_000 }).catch(() => false)) {
    await row.click();
    await page.waitForURL(/\/JobDetail\?id=/i, { timeout: 20_000 }).catch(() => {});
    if (/JobDetail/i.test(page.url()) && (await isOurJob(page))) {
      const url = page.url().replace(/&tab=[^&]*/, '');
      const jobId = await readJobId(page);
      writeCache(url, jobId);
      return { url, jobId };
    }
  }

  return createQaJob(page);
}

async function readJobId(page: Page): Promise<string> {
  const text = await page.getByText(/^#JOB-\d+$/).first().innerText();
  return text.trim().slice(1);
}

/** New Job: клиент QA-quota client (адрес из карточки), Repair, описание JOB_TITLE, без техника → Create Job. */
async function createQaJob(page: Page): Promise<{ url: string; jobId: string }> {
  await page.goto('/JobForm?action=new');
  const client = page.getByLabel('Client Name *');
  await client.pressSequentially('QA-quota', { delay: 20 });
  await page.getByRole('button').filter({ hasText: 'QA-quota client' }).first().click();
  await expect(client).toHaveValue('QA-quota client');
  await expect(page.getByRole('textbox', { name: /^Address/ })).not.toHaveValue('');
  await page.getByRole('combobox').filter({ hasText: 'Select job type' }).click();
  await page.getByRole('option', { name: 'Repair', exact: true }).click();
  await page.getByLabel('Job Description').fill(JOB_TITLE);
  await page.getByRole('button', { name: 'Create Job', exact: true }).click();
  await page.waitForURL(/\/JobDetail\?id=/, { timeout: 30_000 });
  const url = page.url().replace(/&tab=[^&]*/, '');
  await page.goto(url);
  const jobId = await readJobId(page);
  writeCache(url, jobId);
  return { url, jobId };
}

export { jobRow, openJobsTab };
